/**
 * Designed to work with the Project Progress Spreadsheet and Google Drive so that we can select PDFs from our google drive that go into the CE documents and have them auto-merged into the CE document.  
 * 
 * To do list:
 * -Test File Permissions issues
 * -Figure out what order the PDFs will need to go into the document? 
 *    -What specific columns will be needed. 
 *    -Can Boilerplate pages - Coverpages, Section pages, etc be autogenerated/stored?
 */
/**
 * Creates a custom menu in Google Sheets
 * The (e) parameter allows us to detect HOW the script was triggered.
 */
function onOpen(e) {
  // If this was triggered by a time-driven event, it will have a triggerUid.
  // We immediately exit to prevent any UI code from running in the background.
  if (e && e.triggerUid) {
    return;
  }
  
  try {
    var ui = SpreadsheetApp.getUi();
    ui.createMenu('PDF Tools')
        .addItem('Merge PDFs', 'mergePDFs')
        .addToUi();
  } catch (err) {
    Logger.log("Could not create custom menu: " + err.message);
  }
}

/**
 * Main function to evaluate rows and merge PDFs
 */
async function mergePDFs() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet(); 
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  const richTextValues = dataRange.getRichTextValues();
  const sheetId = sheet.getSheetId();
  
  // --- POLYFILLS FOR APPS SCRIPT ---
  if (typeof setTimeout === 'undefined') {
    globalThis.setTimeout = function(callback, delay) {
      Utilities.sleep(delay || 0);
      if (typeof callback === 'function') return callback();
    };
  }
  if (typeof clearTimeout === 'undefined') {
    globalThis.clearTimeout = function() {};
  }
  // ---------------------------------
  
  // Load pdf-lib for merging PDFs natively in Apps Script
  const cdnjs = "https://cdn.jsdelivr.net/npm/pdf-lib/dist/pdf-lib.min.js";
  eval(UrlFetchApp.fetch(cdnjs).getContentText());
  
  // --- DYNAMIC COLUMN FINDING ---
  const headers = values[0]; // Row 1 headers
  
  // Find column indices by exact header name (case-insensitive)
  const COL_COMPLETE = headers.findIndex(h => h.toString().toLowerCase().trim() === 'progress');
  const COL_RECOMPILE = headers.findIndex(h => h.toString().toLowerCase().trim() === 'compile pdf override');
  const COL_FINAL = headers.findIndex(h => h.toString().toLowerCase().trim() === 'merged document');
  const COL_PROJECT = headers.findIndex(h => h.toString().toLowerCase().trim() === 'project');
  
  // Abort silently if columns are missing (prevents UI errors in background)

  if (COL_COMPLETE === -1 || COL_RECOMPILE === -1 || COL_FINAL === -1 || COL_PROJECT === -1) {
    Logger.log("Error: Could not find one or more required columns ('Progress', 'Compile PDF Override', 'Merged Document', or 'Project').");
    return;
  }
  
  // Fetch Advanced API data to read Smart Chips properly
  const sheetName = sheet.getName();
  const dataRangeA1 = dataRange.getA1Notation(); 
  const apiResponse = Sheets.Spreadsheets.get(ss.getId(), {
    ranges: [`'${sheetName}'!${dataRangeA1}`], 
    fields: "sheets(data(rowData(values(userEnteredValue,chipRuns))))"
  });
  const apiRows = apiResponse.sheets[0].data[0].rowData;
  
  for (let r = 1; r < values.length; r++) { // Skip header row
    const complete = values[r][COL_COMPLETE];
    const recompile = values[r][COL_RECOMPILE];
    const finalFile = values[r][COL_FINAL];
    const projectName = values[r][COL_PROJECT] || "Unknown_Project"; // Fallback if project cell is empty
    
    // Check if we should compile: Progress is 100% AND (not compiled yet OR override is checked)
    const isComplete = (complete === 1 || complete === '100%' || complete === 100);
    
    if (isComplete && (!finalFile || recompile === true)) {
      
      let fileIds = [];
      
      // 1. Extract File IDs from Smart Chips (Advanced API)
      if (apiRows[r] && apiRows[r].values) {
        for (let c = 0; c < apiRows[r].values.length; c++) {
          // Skip our control columns so we don't accidentally scan them for PDFs
          if (c === COL_COMPLETE || c === COL_RECOMPILE || c === COL_FINAL || c === COL_PROJECT) continue;
          
          let cell = apiRows[r].values[c];
          if (cell && cell.chipRuns) {
            cell.chipRuns.forEach(run => {
              let uri = run.chip?.richLinkProperties?.uri;
              if (uri && uri.includes('drive.google.com')) {
                let match = uri.match(/[-\w]{25,}/);
                if (match) fileIds.push(match[0]);
              }
            });
          }
        }
      }
      
      // 2. Extract from standard hyperlinks just in case (Native API)
      for (let c = 0; c < values[r].length; c++) {
        // Skip our control columns
        if (c === COL_COMPLETE || c === COL_RECOMPILE || c === COL_FINAL || c === COL_PROJECT) continue;
        
        const rtv = richTextValues[r][c];
        if (!rtv) continue;
        const runs = rtv.getRuns();
        for (let i = 0; i < runs.length; i++) {
          const url = runs[i].getLinkUrl();
          if (url && url.includes('drive.google.com')) {
            const match = url.match(/[-\w]{25,}/);
            if (match) fileIds.push(match[0]);
          }
        }
      }
      
      // 3. Deduplicate IDs
      fileIds = [...new Set(fileIds)];
      
      if (fileIds.length === 0) continue;
      
      // 4. Get Drive Files & Update Permissions
      let files = [];
      for (let i = 0; i < fileIds.length; i++) {
        try {
          let currentFile = DriveApp.getFileById(fileIds[i]);
          
          // Attempt to set permissions so anyone can view the source files
          try {
            currentFile.setSharing(DriveApp.Access.ANYONE, DriveApp.Permission.VIEW);
          } catch (permError) {
            Logger.log("Could not update permissions for file ID: " + fileIds[i] + " - " + permError);
          }
          
          files.push(currentFile);
        } catch(e) {
          Logger.log("Could not access file ID: " + fileIds[i]);
        }
      }
      
      if (files.length === 0) continue;
      
      // 5. Merge PDFs
      const mergedPdf = await PDFLib.PDFDocument.create();
      for (let i = 0; i < files.length; i++) {
        try {
          if (files[i].getMimeType() === MimeType.PDF) {
            const pdfBytes = new Uint8Array(files[i].getBlob().getBytes());
            const pdfDoc = await PDFLib.PDFDocument.load(pdfBytes);
            const copiedPages = await mergedPdf.copyPages(pdfDoc, pdfDoc.getPageIndices());
            copiedPages.forEach((page) => mergedPdf.addPage(page));
          }
        } catch (e) {
          Logger.log("Error processing file " + files[i].getName() + ": " + e);
        }
      }
      
      const mergedBytes = await mergedPdf.save();
      
      // NEW FILE NAMING CONVENTION HERE
      const finalFileName = projectName + " CE.pdf";
      const blob = Utilities.newBlob([...new Int8Array(mergedBytes)], MimeType.PDF, finalFileName);
      
      // 6. Determine Output Folder based on logic
      const targetFolder = determineTargetFolder(files);
      
      // 7. Save File & Set Permissions for Output
      const newFile = targetFolder.createFile(blob);
      
      try {
        // Changed to EDIT so the final document can be signed
        newFile.setSharing(DriveApp.Access.ANYONE, DriveApp.Permission.EDIT);
      } catch (e) {
        Logger.log("Could not set sharing on final file: " + e);
      }
      
      const newFileUrl = newFile.getUrl();
      
      // 8. Output as a Smart Chip using the Advanced Sheets API
      const requests = [{
        updateCells: {
          range: {
            sheetId: sheetId,
            startRowIndex: r,
            endRowIndex: r + 1,
            startColumnIndex: COL_FINAL,
            endColumnIndex: COL_FINAL + 1
          },
          rows: [{
            values: [{
              userEnteredValue: { stringValue: "@" }, // The '@' is required as a placeholder for the chip
              chipRuns: [{
                chip: {
                  richLinkProperties: {
                    uri: newFileUrl
                  }
                }
              }]
            }]
          }],
          fields: "userEnteredValue,chipRuns"
        }
      }];
      
      Sheets.Spreadsheets.batchUpdate({ requests: requests }, ss.getId());
      
      // 9. Uncheck recompile (Override)
      sheet.getRange(r + 1, COL_RECOMPILE + 1).setValue(false); 
      SpreadsheetApp.flush(); 
    }
  }
}

/**
 * Determines the best folder to save the merged PDF based on the input files.
 */
function determineTargetFolder(files) {
  if (files.length === 0) return DriveApp.getRootFolder();
  
  let folderCounts = {};
  let folderObjects = {};
  
  // Traverse up the directory tree for all files to count common parents
  for (let i = 0; i < files.length; i++) {
    let parents = files[i].getParents();
    if (parents.hasNext()) {
      let current = parents.next();
      while (current) {
        let id = current.getId();
        folderCounts[id] = (folderCounts[id] || 0) + 1;
        folderObjects[id] = current;
        
        let nextParents = current.getParents();
        current = nextParents.hasNext() ? nextParents.next() : null;
      }
    }
  }
  
  let maxCount = 0;
  let bestFolderId = null;
  
  // Find the folder with the highest occurrence across all files
  for (let id in folderCounts) {
    if (folderCounts[id] > maxCount) {
      maxCount = folderCounts[id];
      bestFolderId = id;
    }
  }
  
  // If a shared parent exists (even if it's just the most common one)
  if (maxCount > 1 && bestFolderId) {
     return folderObjects[bestFolderId]; 
  } else if (files.length === 1 && bestFolderId) {
     return folderObjects[bestFolderId];
  }
  
  // Fallback: Create or find My Drive\Documents\merged
  try {
    let folders = DriveApp.getRootFolder().getFoldersByName("Documents");
    let docsFolder = folders.hasNext() ? folders.next() : DriveApp.getRootFolder().createFolder("Documents");
    let mergedFolders = docsFolder.getFoldersByName("merged");
    return mergedFolders.hasNext() ? mergedFolders.next() : docsFolder.createFolder("merged");
  } catch(e) {
    return DriveApp.getRootFolder(); // Ultimate fallback
  }
}

/**
 * Opens the custom file upload popup
 */
function openUploadDialog() {
  var html = HtmlService.createHtmlOutputFromFile('Upload')
      .setWidth(400)
      .setHeight(150);
  SpreadsheetApp.getUi().showModalDialog(html, 'Upload File to Google Drive');
}

/**
 * Receives the file from the HTML popup, saves it, sets permissions, and inserts the chip
 */
function saveFileAndInsertChip(base64Data, fileName, mimeType) {
  try {
    // 1. Decode the base64 file data
    var data = Utilities.base64Decode(base64Data);
    var blob = Utilities.newBlob(data, mimeType, fileName);
    
    // 2. Save to Drive (saves to root folder by default)
    var file = DriveApp.createFile(blob);
    
    // 3. Set Permissions automatically
    file.setSharing(DriveApp.Access.ANYONE, DriveApp.Permission.VIEW);
    
    // 4. Get the cell the user currently has selected
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getActiveSheet();
    var cell = sheet.getActiveCell();
    var fileUrl = file.getUrl();
    
    // 5. Insert as a Smart Chip using Advanced Sheets API
    var requests = [{
      updateCells: {
        range: {
          sheetId: sheet.getSheetId(),
          startRowIndex: cell.getRow() - 1,
          endRowIndex: cell.getRow(),
          startColumnIndex: cell.getColumn() - 1,
          endColumnIndex: cell.getColumn()
        },
        rows: [{
          values: [{
            userEnteredValue: { stringValue: "@" },
            chipRuns: [{
              chip: {
                richLinkProperties: {
                  uri: fileUrl
                }
              }
            }]
          }]
        }],
        fields: "userEnteredValue,chipRuns"
      }
    }];
    
    Sheets.Spreadsheets.batchUpdate({ requests: requests }, ss.getId());
    
    return "Success! File uploaded and inserted.";
  } catch (e) {
    return "Error: " + e.toString();
  }
}